<?php
namespace Tests\Feature;
use App\Models\{User,Owner,Venue,VenueDomain,PlatformSetting,DesignAsset};use App\Services\{VenueDomains,DomainNetwork,VenueSettings};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{Http,Storage};use Illuminate\Support\Str;use Tests\TestCase;
class VenueDomainTest extends TestCase {
 use RefreshDatabase;
 protected function setUp():void{parent::setUp();config(['domains.enabled'=>true,'portal.customer_url'=>'https://reservas.platform.com','portal.owner_url'=>'https://gestion.platform.com']);}
 private function owner(bool $admin=false):Owner{return Owner::unguarded(fn()=>Owner::create(['user_id'=>User::factory()->create()->id,'name'=>'Dueño','email'=>Str::random(8).'@example.com','password'=>'Password12345','activated'=>true,'email_verified_at'=>now(),'platform_admin'=>$admin]));}
 private function venue(Owner $o):Venue{return Venue::create(['owner_id'=>$o->user_id,'owner_account_id'=>$o->id,'name'=>'Jardín Magnolia','slug'=>'jardin-'.Str::lower(Str::random(6)),'published'=>true,'settings'=>array_replace(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>0,'included_hours'=>8,'weekday_price'=>100000,'weekend_price'=>100000,'holiday_price'=>100000,'extra_hour_price'=>0,'deposit_value'=>30]),'design'=>['brand_name'=>'Magnolia','page_title'=>'Celebra en Magnolia','favicon_id'=>null]]);}
 private function enable():void{PlatformSetting::create(['id'=>1,'settings'=>['independent_sites_enabled'=>true]]);}
 public function test_disabled_feature_blocks_saved_domains_and_management_without_deleting_data():void{
  $this->enable();$o=$this->owner(true);$v=$this->venue($o);$site=$this->site($v);config(['domains.enabled'=>false,'app.env'=>'production','domains.acme_email'=>'admin@platform.com']);
  $domains=app(VenueDomains::class);$this->assertFalse($domains->generalEnabled());$this->assertFalse($domains->active($site));
  $this->actingAs($o)->getJson('https://gestion.platform.com/api/owner/sites/settings')->assertNotFound();
  $this->putJson('https://gestion.platform.com/api/owner/sites/settings',['enabled'=>true])->assertNotFound();
  $this->putJson('https://gestion.platform.com/api/owner/venues/'.$v->slug.'/site',['hostname'=>'otro.example.com'])->assertNotFound();
  $this->app['env']='production';$this->get('https://'.$site->hostname.'/')->assertNotFound();
  $this->get('https://'.$site->hostname.'/.well-known/encuentro-domain/'.$site->verification_token)->assertNotFound();
  $this->assertDatabaseHas('venue_domains',['id'=>$site->id,'hostname'=>$site->hostname,'enabled'=>true]);
  $this->assertStringNotContainsString($site->hostname,$domains->caddyfile());
  $this->getJson('https://reservas.platform.com/api/platform-branding')->assertOk();
 }
 private function site(Venue $v,array $extra=[]):VenueDomain{return VenueDomain::create(array_replace(['venue_id'=>$v->id,'hostname'=>'magnolia.example.com','verification_token'=>Str::random(64),'enabled'=>true,'dns_verified_at'=>now(),'https_verified_at'=>now()],$extra));}
 public function test_owner_can_request_domain_but_cannot_enable_feature_or_activate_site():void{$o=$this->owner();$v=$this->venue($o);$this->actingAs($o)->putJson('/api/owner/venues/'.$v->slug.'/site',['hostname'=>'magnolia.example.com'])->assertOk()->assertJsonPath('site.enabled',false)->assertJsonPath('can_activate',false);$this->putJson('/api/owner/venues/'.$v->slug.'/site',['hostname'=>'magnolia.example.com','enabled'=>true])->assertForbidden();$this->putJson('/api/owner/sites/settings',['enabled'=>true])->assertForbidden();}
 public function test_admin_can_manage_other_owners_domains_and_requires_both_checks():void{$v=$this->venue($this->owner());$this->actingAs($this->owner(true));$this->putJson('/api/owner/sites/settings',['enabled'=>true])->assertOk();$this->getJson('/api/owner/sites/venues')->assertOk()->assertJsonPath('data.0.id',$v->id);$site=$this->site($v,['enabled'=>false,'https_verified_at'=>null]);$url='/api/owner/venues/'.$v->slug.'/site';$this->putJson($url,['hostname'=>$site->hostname,'enabled'=>true])->assertUnprocessable();$site->update(['https_verified_at'=>now()]);$this->putJson($url,['hostname'=>$site->hostname,'enabled'=>true])->assertOk()->assertJsonPath('site.active',true);}
 public function test_other_owner_cannot_read_or_change_domain_or_verification_value():void{$v=$this->venue($this->owner());$site=$this->site($v);$this->actingAs($this->owner());$url='/api/owner/venues/'.$v->slug.'/site';$this->getJson($url)->assertForbidden()->assertDontSee($site->verification_token);$this->postJson($url.'/verify/dns')->assertForbidden();}
 public function test_hostname_rejects_urls_private_names_wildcards_and_platform_domains():void{$o=$this->owner();$v=$this->venue($o);$this->actingAs($o);foreach(['https://magnolia.com','magnolia.com/path','magnolia.com:8443','*.magnolia.com','127.0.0.1','local.internal','localhost','reservas.platform.com','gestion.platform.com',"domain.com\nadmin.com"] as $host)$this->putJson('/api/owner/venues/'.$v->slug.'/site',['hostname'=>$host])->assertUnprocessable();}
 public function test_changing_hostname_clears_proof_and_activation_and_duplicate_is_rejected():void{$o=$this->owner();$v=$this->venue($o);$site=$this->site($v);$old=$site->verification_token;$this->actingAs($o)->putJson('/api/owner/venues/'.$v->slug.'/site',['hostname'=>'nuevo.example.com'])->assertOk()->assertJsonPath('site.enabled',false)->assertJsonPath('site.dns_verified_at',null);$this->assertNotSame($old,$site->fresh()->verification_token);$other=$this->venue($o);$this->putJson('/api/owner/venues/'.$other->slug.'/site',['hostname'=>'nuevo.example.com'])->assertUnprocessable();}
 public function test_dns_verification_requires_exact_txt_and_loss_disables_site():void{$this->enable();$o=$this->owner();$v=$this->venue($o);$site=$this->site($v);$net=\Mockery::mock(DomainNetwork::class);$net->shouldReceive('txt')->with('_encuentro.'.$site->hostname)->once()->andReturn(['encuentro-verification='.$site->verification_token]);$this->app->instance(DomainNetwork::class,$net);$this->actingAs($o)->postJson('/api/owner/venues/'.$v->slug.'/site/verify/dns')->assertOk()->assertJsonPath('site.dns_fresh',true);$net2=\Mockery::mock(DomainNetwork::class);$net2->shouldReceive('txt')->once()->andReturn(['encuentro-verification=incorrecto']);$this->app->instance(DomainNetwork::class,$net2);$this->postJson('/api/owner/venues/'.$v->slug.'/site/verify/dns')->assertOk()->assertJsonPath('site.enabled',false)->assertJsonPath('site.dns_fresh',false);}
 public function test_https_verification_requires_dns_and_never_auto_activates():void{$this->enable();$o=$this->owner();$v=$this->venue($o);$site=$this->site($v,['enabled'=>false,'dns_verified_at'=>null,'https_verified_at'=>null]);$net=\Mockery::mock(DomainNetwork::class);$net->shouldReceive('https')->with($site->hostname,$site->verification_token)->once()->andReturn(true);$this->app->instance(DomainNetwork::class,$net);$this->actingAs($o);$url='/api/owner/venues/'.$v->slug.'/site/verify/https';$this->postJson($url)->assertUnprocessable();$site->update(['dns_verified_at'=>now()]);$this->postJson($url)->assertOk()->assertJsonPath('site.https_fresh',true)->assertJsonPath('site.enabled',false);}
 public function test_active_domain_serves_only_its_venue_without_session_cookie_or_token_leak():void{$this->enable();$v=$this->venue($this->owner());$site=$this->site($v);$this->get('https://'.$site->hostname.'/')->assertOk()->assertSee('standalone-site')->assertSee('Celebra en Magnolia')->assertDontSee($site->verification_token)->assertHeader('Strict-Transport-Security','max-age=31536000');$this->assertEmpty($this->app['session']->all());$this->getJson('https://'.$site->hostname.'/api/venues/'.$v->slug)->assertOk()->assertJsonPath('id',$v->id);$this->getJson('https://'.$site->hostname.'/api/me')->assertNotFound();$this->postJson('https://'.$site->hostname.'/api/login',[])->assertNotFound();$this->postJson('https://'.$site->hostname.'/api/bookings/fake/checkout',[])->assertNotFound();}
 public function test_cross_venue_data_and_assets_are_not_available_on_custom_domain():void{$this->enable();$v=$this->venue($this->owner());$site=$this->site($v);$other=$this->venue($this->owner());$this->getJson('https://'.$site->hostname.'/api/venues/'.$other->slug)->assertNotFound();$asset=DesignAsset::create(['venue_id'=>$other->id,'kind'=>'logo','path'=>'other-logo.png']);$this->get('https://'.$site->hostname.'/api/media/branding/'.$asset->id)->assertNotFound();$this->getJson('https://'.$site->hostname.'/api/venues')->assertNotFound();}
 public function test_expired_proof_disabled_general_and_unpublished_venue_stop_site():void{$this->enable();$v=$this->venue($this->owner());$site=$this->site($v);$site->update(['dns_verified_at'=>now()->subDays(8)]);$this->get('https://'.$site->hostname.'/')->assertNotFound();$site->update(['dns_verified_at'=>now()]);$v->update(['published'=>false]);$this->get('https://'.$site->hostname.'/')->assertNotFound();$v->update(['published'=>true]);PlatformSetting::whereKey(1)->update(['settings'=>json_encode(['independent_sites_enabled'=>false])]);$this->get('https://'.$site->hostname.'/')->assertNotFound();}
 public function test_http_redirects_to_same_verified_hostname_and_owner_portal_cannot_serve_custom_site():void{$this->enable();$v=$this->venue($this->owner());$site=$this->site($v);$this->get('http://'.$site->hostname.'/')->assertStatus(308)->assertRedirect('https://'.$site->hostname.'/');config(['portal.kind'=>'owner']);$this->get('https://'.$site->hostname.'/')->assertNotFound();}
 public function test_https_probe_can_run_before_activation_but_only_for_verified_domain():void{$this->enable();$v=$this->venue($this->owner());$site=$this->site($v,['enabled'=>false,'https_verified_at'=>null]);$this->get('https://'.$site->hostname.'/.well-known/encuentro-domain/'.$site->verification_token)->assertOk()->assertContent('encuentro-domain:'.$site->verification_token);$this->get('https://'.$site->hostname.'/')->assertNotFound();$site->update(['dns_verified_at'=>null]);$this->get('https://'.$site->hostname.'/.well-known/encuentro-domain/'.$site->verification_token)->assertNotFound();}
 public function test_network_verifier_rejects_private_and_rebinding_targets_without_http():void{Http::fake();$net=\Mockery::mock(DomainNetwork::class)->makePartial();$net->shouldReceive('addresses')->andReturn(['127.0.0.1']);$this->assertFalse($net->https('magnolia.example.com',str_repeat('a',64)));Http::assertNothingSent();$real=new DomainNetwork;foreach(['127.0.0.1','10.1.2.3','192.168.0.1','169.254.169.254','::1','::ffff:127.0.0.1','::127.0.0.1','64:ff9b::7f00:1','2002:7f00:0001::1','224.0.0.1','fc00::1','2001:db8::1'] as $ip)$this->assertFalse($real->publicAddress($ip),$ip);$this->assertTrue($real->publicAddress('1.1.1.1'));}
 public function test_https_verifier_rejects_redirect_and_accepts_only_exact_challenge():void{$token=str_repeat('b',64);$net=\Mockery::mock(DomainNetwork::class)->makePartial();$net->shouldReceive('addresses')->andReturn(['1.1.1.1']);Http::fake(['https://magnolia.example.com/*'=>Http::sequence()->push('encuentro-domain:'.$token)->push('',302,['Location'=>'http://127.0.0.1'])]);$this->assertTrue($net->https('magnolia.example.com',$token));$this->assertFalse($net->https('magnolia.example.com',$token));}
 public function test_caddy_export_contains_only_explicit_canonical_and_dns_verified_domains():void{$this->enable();config(['domains.acme_email'=>'admin@example.com']);$v=$this->venue($this->owner());$site=$this->site($v,['enabled'=>false,'https_verified_at'=>null]);$other=$this->site($this->venue($this->owner()),['hostname'=>'pending.example.com','dns_verified_at'=>null]);$config=app(VenueDomains::class)->caddyfile();$this->assertStringContainsString('magnolia.example.com',$config);$this->assertStringContainsString('reverse_proxy web-owner:80',$config);$this->assertStringNotContainsString('pending.example.com',$config);$this->assertStringNotContainsString('on_demand',$config);$this->assertStringNotContainsString($site->verification_token,$config);}
 public function test_anonymous_quote_uses_shared_server_prices_and_does_not_create_reservation():void{$this->enable();$v=$this->venue($this->owner());$site=$this->site($v);$this->postJson('https://'.$site->hostname.'/api/venues/'.$v->slug.'/quote',['date'=>now('America/Mexico_City')->addMonth()->format('Y-m-d'),'start'=>14,'hours'=>8,'guests'=>10,'total'=>1])->assertOk()->assertJsonPath('quote.total',100000);$this->assertDatabaseCount('bookings',0);}
 public function test_production_default_owner_signup_requires_invitation():void{
  config(['portal.kind'=>'owner']);$this->postJson('/api/owner-auth/register',['name'=>'Intruso','email'=>'other@example.com','password'=>'Password12345','password_confirmation'=>'Password12345'])->assertForbidden();$this->assertDatabaseCount('owners',0);$this->getJson('/api/me')->assertOk()->assertJsonPath('portal.owner_signup',false);
 }
 public function test_failed_https_recheck_clears_previous_proof_and_disables_site():void{
  $this->enable();$o=$this->owner();$v=$this->venue($o);$site=$this->site($v);$net=\Mockery::mock(DomainNetwork::class);$net->shouldReceive('https')->once()->andReturn(false);$this->app->instance(DomainNetwork::class,$net);$this->actingAs($o)->postJson('/api/owner/venues/'.$v->slug.'/site/verify/https')->assertOk()->assertJsonPath('site.https_fresh',false)->assertJsonPath('site.enabled',false);
 }
 public function test_existing_venue_slug_is_immutable_to_keep_payment_callbacks_and_links():void{
  $o=$this->owner();$v=$this->venue($o);$this->actingAs($o)->putJson('/api/owner/venues/'.$v->slug,['name'=>$v->name,'slug'=>'new-slug','published'=>false,'settings'=>$v->settings])->assertUnprocessable()->assertJsonValidationErrors('slug');$this->assertSame($v->slug,$v->fresh()->slug);
 }
 public function test_domain_cannot_be_active_if_central_account_or_checkout_uses_http():void{
  $this->enable();$v=$this->venue($this->owner());$site=$this->site($v,['enabled'=>false]);config(['portal.customer_url'=>'http://reservas.platform.com']);$this->actingAs($this->owner(true))->putJson('/api/owner/venues/'.$v->slug.'/site',['hostname'=>$site->hostname,'enabled'=>true])->assertUnprocessable();$this->assertFalse(app(VenueDomains::class)->active($site));
 }
 public function test_network_resolver_follows_cname_with_a_bounded_loop():void{
  $net=\Mockery::mock(DomainNetwork::class)->makePartial()->shouldAllowMockingProtectedMethods();$net->shouldReceive('records')->with('magnolia.example.com')->once()->andReturn([['type'=>'CNAME','target'=>'origin.example.com.']]);$net->shouldReceive('records')->with('origin.example.com')->once()->andReturn([['type'=>'A','ip'=>'1.1.1.1']]);$this->assertSame(['1.1.1.1'],$net->addresses('magnolia.example.com'));
  $loop=\Mockery::mock(DomainNetwork::class)->makePartial()->shouldAllowMockingProtectedMethods();$loop->shouldReceive('records')->with('loop.example.com')->once()->andReturn([['type'=>'CNAME','target'=>'loop.example.com']]);$this->assertSame([],$loop->addresses('loop.example.com'));
 }
}
